const P = {"tool": "Mission Operations Rehearsal Simulator", "r1": 7281, "r2": 42164};

function demoMain(P){
  var mu=398600.4418, r1=P.r1, r2=P.r2, a=(r1+r2)/2;
  var dv1=Math.sqrt(mu/r1)*(Math.sqrt(2*r2/(r1+r2))-1);
  var dv2=Math.sqrt(mu/r2)*(1-Math.sqrt(2*r1/(r1+r2)));
  var tof=Math.PI*Math.sqrt(Math.pow(a,3)/mu)/3600;
  return 'Hohmann transfer ('+P.tool+'): r1='+r1+'km r2='+r2+'km dv1='+dv1.toFixed(3)+'km/s dv2='+dv2.toFixed(3)+'km/s total='+(dv1+dv2).toFixed(3)+'km/s coast='+tof.toFixed(1)+'h';
}
console.log(demoMain(P));

